package seleniumfeb;

public class AssignmentTwo {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		 //reverse 
		String [] namee={"Preethi","nithya","varun"};
	    for(int i=namee.length-1;i>=0;i--)
	    {
	    	System.out.println(namee[i]);
	    }
	    
	    //convert
	    String greet="Welcome";
	    for(int i=greet.length()-1;i>=0;i--)
	    {
	    	System.out.println(greet.charAt(i));
	    }
	    
	    String [] msg= {"Hey","you're","beautiful"};
	    for(int i=msg.length-1;i>=0;i--)
	    {
	    System.out.println(msg[i]);
	    }
	    
	    String fruit = "apple";
	    for (int i=fruit.length()-1;i>=0;i--) {
	    System.out.println(fruit.charAt(i));
	    }

	    
	    String colour="Black";
	    for(int i=0;i<colour.length();i++)
	    	System.out.println(colour.charAt(i));
	    
	    //To print reverse string
	    String fruits="Mango";
	    for(int i=fruits.length()-1;i>=0;i--)
	    {
	    	System.out.println(fruits.charAt(i));
	    }
	    
	    
	    }
	}


